/**
 * Registry panduan interaktif (product tour). Murni data — tidak ada logika progres atau render di sini,
 * supaya role lain bisa ditambahkan tanpa membangun ulang mesin tour (lihat src/components/tutorial/).
 * Role yang sudah diisi: "pemohon" (pengunjung publik, tanpa akun — progres per-browser), "manager", dan
 * "staff" (akun internal — progres per-akun, lihat namespace di tutorial-context.tsx / tutorial-progress.ts).
 * "staff" adalah peran PIC (Person In Charge) di database/sesi — istilah "PIC" dipakai di seluruh teks
 * panduan ini karena itu sebutan bisnis yang dipakai di aplikasi, tapi kunci role tetap "staff" (lihat
 * src/lib/auth/permissions.ts) supaya konsisten dengan pemeriksaan akses sungguhan.
 * Role Super Admin BELUM diisi — lihat pembatasan di src/app/dtic/(panel)/panduan/page.tsx.
 */

export type TutorialRole = "pemohon" | "manager" | "staff";

/** Ikon diresolusi di layer komponen (lucide-react) — modul ini tetap murni data, tanpa import React. */
export type TutorialIcon = "LayoutDashboard" | "FilePlus2" | "Search" | "CheckCircle2" | "MessageCircleQuestion" | "ListChecks" | "ShieldCheck" | "Users";

export type TutorialStepTarget = {
  /** Halaman tempat elemen ini berada (pathname persis). Di luar halaman ini, target tidak dicari. */
  page: string;
  /** CSS selector elemen asli di aplikasi (atribut data-tour=, bukan kelas styling yang bisa berubah). */
  selector: string;
  /**
   * Untuk formulir pengajuan bertahap (lihat submission-form.tsx): langkah wizard (0=Kategori, 1=Detail
   * pekerjaan, 2=Tim & deadline, 3=Tinjau) tempat elemen ini SEBENARNYA terlihat. Tanpa ini, tour bisa
   * menjelaskan elemen yang masih disembunyikan `hidden` karena wizard belum dipindah ke langkah itu —
   * tour men-sinkronkan wizard ke langkah ini sebelum mencari targetnya (hanya saat mode simulasi aktif).
   */
  wizardStep?: number;
};

/**
 * Demonstrasi LANGSUNG pada field formulir ASLI (lihat submission-form.tsx useFormDemo) — bukan kotak
 * simulasi terpisah. `selector` menunjuk elemen asli (id input sungguhan); animasi mengetik dijalankan
 * dengan memanipulasi DOM elemen itu secara langsung (field-field ini TIDAK controlled oleh React, nilainya
 * dibaca lewat FormData saat pengajuan — lihat collect() — sehingga aman dimanipulasi dan 100% dikembalikan
 * kosong saat tour berakhir, lihat resetFormDemo()). `pulseSelector` untuk kontrol non-teks (kartu
 * kategori/dropdown) — sorotan berkedip pada elemen SUNGGUHAN, bukan mengubah pilihan pengguna. `richText`
 * khusus editor deskripsi (Tiptap, lihat rich-text-editor.tsx demoText). `file` khusus area unggah asli.
 */
export type FormDemoField = { selector: string; text: string };
export type FormDemo = {
  fields?: FormDemoField[];
  richText?: { selector: string; text: string };
  pulseSelector?: string;
  file?: { fileName: string; fileSize: string };
};

export type TutorialStep = {
  title: string;
  body: string;
  /** Tanpa target = langkah penjelasan biasa (tanpa sorotan) — dipakai saat elemen tidak selalu terlihat. */
  target?: TutorialStepTarget;
  /** Tombol opsional yang membawa pengguna ke halaman lain agar tour bisa dilanjutkan di sana. */
  navigateTo?: string;
  /**
   * Untuk langkah yang menjelaskan "klik baris ini" pada target yang SUDAH tersorot di halaman saat ini
   * (misalnya baris daftar pekerjaan): menekan "Berikutnya" otomatis mengklik tautan sungguhan di dalam
   * elemen target (bukan sekadar menyuruh pengguna mengklik sendiri) sebelum pindah ke langkah berikutnya —
   * pengguna sering tidak sadar overlay tour bisa ditembus klik (pointer-events-none di wadah luar, lihat
   * product-tour.tsx), sehingga langkah oportunistik berikutnya (target di halaman lain) terlihat macet.
   * Aman untuk akun tanpa data sama sekali: bila elemen/tautan tidak ditemukan, klik dilewati tanpa error.
   */
  clickTargetOnAdvance?: boolean;
  /** Demonstrasi pengisian pada field ASLI — lihat FormDemo. Data simulasi, tidak pernah dikirim/disimpan. */
  formDemo?: FormDemo;
};

/**
 * Perilaku tombol di langkah terakhir (lihat ProductTour):
 * - "start_request": tutorial INI SENDIRI adalah pengantar pengajuan → satu tombol "Selesai dan Mulai
 *   Pengajuan" yang menutup tour dan membuka formulir pengajuan dalam kondisi NORMAL (bukan simulasi).
 * - "generic" (atau tidak diisi): tahap penutup umum → dua pilihan, "Kembali ke Awal" (hubPath, default
 *   "/panduan" — hub publik pemohon) dan tombol kedua (secondaryAction, default "Mulai Pengajuan" → "/").
 *   Tutorial Manager mengisi hubPath="/dtic/panduan" dan secondaryAction sesuai konteksnya (lihat TUTORIALS
 *   di bawah) supaya tidak mengarahkan Manager ke hub/form publik pemohon.
 */
export type TutorialCompletion = { kind: "start_request" } | { kind: "generic"; hubPath?: string; secondaryAction?: { label: string; href: string } };

export type Tutorial = {
  id: string;
  role: TutorialRole;
  title: string;
  description: string;
  icon: TutorialIcon;
  estimatedMinutes: number;
  /** Halaman awal yang dibuka saat tutorial ini dimulai dari halaman lain. */
  startPage: string;
  steps: TutorialStep[];
  completion?: TutorialCompletion;
};

