export function tutorialsForRole(role: TutorialRole): Tutorial[] {
  return TUTORIALS.filter((t) => t.role === role);
}

export function getTutorial(id: string): Tutorial | undefined {
  return TUTORIALS.find((t) => t.id === id);
}
